#include "common.hpp"
#include <psapi.h>
#include <iostream>
int main(){std::wstring dir=parent(exePath());std::wstring command=L"\""+pathJoin(dir,L"NetSwitch.exe")+L"\" --smoke-ui";std::vector<wchar_t> buffer(command.begin(),command.end());buffer.push_back(0);STARTUPINFOW si={};si.cb=sizeof(si);PROCESS_INFORMATION p={};if(!CreateProcessW(NULL,buffer.data(),NULL,NULL,FALSE,0,NULL,dir.c_str(),&si,&p))return 1;Sleep(500);PROCESS_MEMORY_COUNTERS_EX counters={};counters.cb=sizeof(counters);bool measured=GetProcessMemoryInfo(p.hProcess,(PROCESS_MEMORY_COUNTERS*)&counters,sizeof(counters))!=0;DWORD wait=WaitForSingleObject(p.hProcess,10000),exit=1;if(wait==WAIT_OBJECT_0)GetExitCodeProcess(p.hProcess,&exit);else TerminateProcess(p.hProcess,5);CloseHandle(p.hThread);CloseHandle(p.hProcess);if(wait!=WAIT_OBJECT_0||exit||!measured){std::cout<<"Tray smoke failed\n";return 1;}std::cout<<"Tray smoke passed: working set "<<(counters.WorkingSetSize/1024)<<" KiB; private bytes "<<(counters.PrivateUsage/1024)<<" KiB (startup-only sample, no service).\n";return 0;}
